<script>
  const textElement = document.getElementById('text-element');
        const container = document.querySelector('.c-86-a30c002c7795');
        
        function scaleText() {
            // 重置字体大小
            textElement.style.fontSize = '172px';
            
            // 获取容器和文本的宽度
            const containerWidth = container.offsetWidth - 20; // 减去padding
            const textWidth = textElement.scrollWidth;
            
            // 如果文本宽度超过容器宽度，则调整字体大小
            if (textWidth > containerWidth) {
                const scaleRatio = containerWidth / textWidth;
                textElement.style.fontSize = (scaleRatio * 172) + 'px';
            }
        }
        
        // 初始缩放和窗口调整时缩放
        window.addEventListener('load', scaleText);
        window.addEventListener('resize', scaleText);
</script>
  <script>
    // 获取所有文本元素和容器
    const textElements = document.querySelectorAll('.text-container');
    const containers = document.querySelectorAll('.b0c65de4a21b');
    
    // 为每个文本元素计算并应用拉伸效果
    function updateAllStretches() {
      textElements.forEach((textElement, index) => {
        const containerWidth = containers[index].clientWidth;
        const textWidth = textElement.scrollWidth;
        const scaleX = containerWidth / textWidth;
        
        if (textWidth > containerWidth) {
          textElement.style.transform = `scaleX(${scaleX})`;
        } else {
          textElement.style.transform = 'none';
        }
      });
    }
    
    // 初始化所有文本的拉伸效果
    updateAllStretches();
    
    // 窗口大小变化时重新计算
    window.addEventListener('resize', updateAllStretches);
  </script>
  
    <script>
    document.addEventListener('DOMContentLoaded', function() {
            const downloadBtn = document.getElementById('downloadBtn');
            const targetDiv = document.getElementById('targetDiv');

            // 定义需要检查的所有字体（与CSS中@font-face的font-family对应）
            const requiredFonts = [
                'OPPOSans',

            ];

            downloadBtn.addEventListener('click', function() {
                // 检查所有字体是否都已加载
                const allFontsLoaded = requiredFonts.every(font => {
                    // 逐个检查每个字体的加载状态
                    return document.fonts.check(`1em ${font}`);
                });

                if (allFontsLoaded) {
                    // 所有字体加载完成，执行截图
                    captureAndDownload(targetDiv);
                } else {
                    // 有字体未加载，进入等待状态
                    downloadBtn.disabled = true;
                    downloadBtn.textContent = '字体加载中...';
                    
                    // 等待所有字体加载完成（document.fonts.ready会监听所有字体）
                    document.fonts.ready.then(function() {
                        downloadBtn.disabled = false;
                        downloadBtn.textContent = '下载特定区域';
                        captureAndDownload(targetDiv);
                    }).catch(function(error) {
                        console.error('字体加载失败:', error);
                        downloadBtn.textContent = '加载失败';
                    });
                }
            });

            function captureAndDownload(element) {
                html2canvas(element, {
                    scale: 1.5,
                    useCORS: true,
                    logging: false
                }).then(function(canvas) {
                    const imgUrl = canvas.toDataURL('image/png');
                    const link = document.createElement('a');
                    link.href = imgUrl;
                    link.download = '多字体区域截图.png';
                    link.click();
                }).catch(function(error) {
                    console.error('截图失败:', error);
                });
            }
        });
    </script>
</body>
